const V1EnvVarSourceSchema = z
  .object({
    configMapKeyRef: V1ConfigMapKeySelectorSchema.exactOptional().openapi({
      description: 'Selects a key of a ConfigMap.\n+optional',
    }),
    fieldRef: V1ObjectFieldSelectorSchema.exactOptional().openapi({
      description:
        "Selects a field of the pod: supports metadata.name, metadata.namespace, `metadata.labels['<KEY>']`, `metadata.annotations['<KEY>']`,\nspec.nodeName, spec.serviceAccountName, status.hostIP, status.podIP, status.podIPs.\n+optional",
    }),
    fileKeyRef: V1FileKeySelectorSchema.exactOptional().openapi({
      description:
        'FileKeyRef selects a key of the env file.\nRequires the EnvFiles feature gate to be enabled.\n\n+featureGate=EnvFiles\n+optional',
    }),
    resourceFieldRef: V1ResourceFieldSelectorSchema.exactOptional().openapi({
      description:
        'Selects a resource of the container: only resources limits and requests\n(limits.cpu, limits.memory, limits.ephemeral-storage, requests.cpu, requests.memory and requests.ephemeral-storage) are currently supported.\n+optional',
    }),
    secretKeyRef: V1SecretKeySelectorSchema.exactOptional().openapi({
      description: "Selects a key of a secret in the pod's namespace\n+optional",
    }),
  })
  .openapi({ required: [] })
  .openapi('V1EnvVarSource')

const V1EnvVarSchema = z
  .object({
    name: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "Name of the environment variable.\nMay consist of any printable ASCII characters except '='.",
      }),
    value: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Variable references $(VAR_NAME) are expanded\nusing the previously defined environment variables in the container and\nany service environment variables. If a variable cannot be resolved,\nthe reference in the input string will be unchanged. Double $$ are reduced\nto a single $, which allows for escaping the $(VAR_NAME) syntax: i.e.\n"$$(VAR_NAME)" will produce the string literal "$(VAR_NAME)".\nEscaped references will never be expanded, regardless of whether the variable\nexists or not.\nDefaults to "".\n+optional',
      }),
    valueFrom: V1EnvVarSourceSchema.exactOptional().openapi({
      description:
        "Source for the environment variable's value. Cannot be used if value is not empty.\n+optional",
    }),
  })
  .openapi({ required: [] })
  .openapi('V1EnvVar')

