const V1HTTPGetActionSchema = z
  .object({
    host: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Host name to connect to, defaults to the pod IP. You probably want to set\n"Host" in httpHeaders instead.\n+optional',
      }),
    httpHeaders: z
      .array(K8sIoApiCoreV1HTTPHeaderSchema)
      .exactOptional()
      .openapi({
        description:
          'Custom headers to set in the request. HTTP allows repeated headers.\n+optional\n+listType=atomic',
      }),
    path: z
      .string()
      .exactOptional()
      .openapi({ description: 'Path to access on the HTTP server.\n+optional' }),
    port: IntstrIntOrStringSchema.exactOptional().openapi({
      description:
        'Name or number of the port to access on the container.\nNumber must be in the range 1 to 65535.\nName must be an IANA_SVC_NAME.',
    }),
    scheme: V1URISchemeSchema.exactOptional().openapi({
      description: 'Scheme to use for connecting to the host.\nDefaults to HTTP.\n+optional',
    }),
  })
  .openapi({ required: [] })
  .openapi('V1HTTPGetAction')

