export const getCustomTemplatesRoute = createRoute({
  method: 'get',
  path: '/custom_templates',
  tags: ['custom_templates'],
  summary: 'List available custom templates',
  description: 'List available custom templates.\n**Access policy**: authenticated',
  operationId: 'CustomTemplateList',
  request: {
    query: z.object({
      type: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(
            z.preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.union([z.literal(1), z.literal(2), z.literal(3)]),
            ),
          ),
        )
        .openapi({
          param: {
            description: 'Template types',
            in: 'query',
            name: 'type',
            required: true,
            style: 'form',
            explode: false,
            schema: { type: 'array', items: { enum: [1, 2, 3], type: 'integer' } },
          },
        }),
      edge: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by edge templates',
            in: 'query',
            name: 'edge',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: z.array(PortainerCustomTemplateSchema) } },
    },
    500: { description: 'Server error' },
  },
  security: [{ ApiKeyAuth: [] }, { jwt: [] }],
})

