export const postCustomTemplatesCreateFileRoute = createRoute({
  method: 'post',
  path: '/custom_templates/create/file',
  tags: ['custom_templates'],
  summary: 'Create a custom template',
  description: 'Create a custom template.\n**Access policy**: authenticated',
  operationId: 'CustomTemplateCreateFile',
  request: {
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              Title: z.string().openapi({ description: 'Title of the template' }),
              Description: z.string().openapi({ description: 'Description of the template' }),
              Note: z
                .string()
                .openapi({
                  description: 'A note that will be displayed in the UI. Supports HTML content',
                }),
              Platform: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.union([z.literal(1), z.literal(2)]),
                )
                .openapi({
                  description: "Platform associated to the template (1 - 'linux', 2 - 'windows')",
                }),
              Type: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.union([z.literal(1), z.literal(2), z.literal(3)]),
                )
                .openapi({
                  description: 'Type of created stack (1 - swarm, 2 - compose, 3 - kubernetes)',
                }),
              File: z.file().openapi({ type: 'string', format: 'binary', description: 'File' }),
              Logo: z
                .string()
                .exactOptional()
                .openapi({ description: "URL of the template's logo" }),
              Variables: z
                .string()
                .exactOptional()
                .openapi({ description: 'A json array of variables definitions' }),
            })
            .openapi({ required: ['Title', 'Description', 'Note', 'Platform', 'Type', 'File'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: { 'application/json': { schema: PortainerCustomTemplateSchema } },
    },
    400: { description: 'Invalid request' },
    500: { description: 'Server error' },
  },
  security: [{ ApiKeyAuth: [] }, { jwt: [] }],
})

