export const postEdgeJobsCreateFileRoute = createRoute({
  method: 'post',
  path: '/edge_jobs/create/file',
  tags: ['edge_jobs'],
  summary: 'Create an EdgeJob from a file',
  description: '**Access policy**: administrator',
  operationId: 'EdgeJobCreateFile',
  request: {
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              file: z
                .file()
                .openapi({
                  type: 'string',
                  format: 'binary',
                  description: 'Content of the Stack file',
                }),
              Name: z.string().openapi({ description: 'Name of the stack' }),
              CronExpression: z
                .string()
                .openapi({ description: 'A cron expression to schedule this job' }),
              EdgeGroups: z
                .string()
                .openapi({ description: 'JSON stringified array of Edge Groups ids' }),
              Endpoints: z
                .string()
                .openapi({ description: 'JSON stringified array of Environment ids' }),
              Recurring: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({ description: 'If recurring' }),
            })
            .openapi({ required: ['file', 'Name', 'CronExpression', 'EdgeGroups', 'Endpoints'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: { 'application/json': { schema: PortainerEdgeGroupSchema } },
    },
    500: { description: 'Internal Server Error' },
    503: { description: 'Edge compute features are disabled' },
  },
  security: [{ ApiKeyAuth: [] }, { jwt: [] }],
})

