export const postEdgeStacksCreateFileRoute = createRoute({
  method: 'post',
  path: '/edge_stacks/create/file',
  tags: ['edge_stacks'],
  summary: 'Create an EdgeStack from file',
  description: '**Access policy**: administrator',
  operationId: 'EdgeStackCreateFile',
  request: {
    query: z.object({
      dryrun: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'if true, will not create an edge stack, but just will check the settings and return a non-persisted edge stack object',
            in: 'query',
            name: 'dryrun',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              Name: z
                .string()
                .openapi({
                  description:
                    'Name of the stack. it must only consist of lowercase alphanumeric characters, hyphens, or underscores as well as start with a letter or number',
                }),
              file: z
                .file()
                .openapi({
                  type: 'string',
                  format: 'binary',
                  description: 'Content of the Stack file',
                }),
              EdgeGroups: z
                .string()
                .openapi({ description: 'JSON stringified array of Edge Groups ids' }),
              DeploymentType: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .openapi({ description: "deploy type 0 - 'compose', 1 - 'kubernetes'" }),
              Registries: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'JSON stringified array of Registry ids to use for this stack',
                }),
              UseManifestNamespaces: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    "Uses the manifest's namespaces instead of the default one, relevant only for kube environments",
                }),
              PrePullImage: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({ description: 'Pre Pull image' }),
              RetryDeploy: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({ description: 'Retry deploy' }),
            })
            .openapi({ required: ['Name', 'file', 'EdgeGroups', 'DeploymentType'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: { 'application/json': { schema: PortainerEdgeStackSchema } },
    },
    400: { description: 'Bad request' },
    500: { description: 'Internal server error' },
    503: { description: 'Edge compute features are disabled' },
  },
  security: [{ ApiKeyAuth: [] }, { jwt: [] }],
})

