export const postEndpointsRoute = createRoute({
  method: 'post',
  path: '/endpoints',
  tags: ['endpoints'],
  summary: 'Create a new environment(endpoint)',
  description:
    'Create a new environment(endpoint) that will be used to manage an environment(endpoint).\n**Access policy**: administrator',
  operationId: 'EndpointCreate',
  request: {
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              Name: z
                .string()
                .openapi({
                  description:
                    'Name that will be used to identify this environment(endpoint) (example: my-environment)',
                }),
              EndpointCreationType: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.union([
                    z.literal(0),
                    z.literal(1),
                    z.literal(2),
                    z.literal(3),
                    z.literal(4),
                    z.literal(5),
                  ]),
                )
                .openapi({
                  description:
                    'Environment(Endpoint) type. Value must be one of: 1 (Local Docker environment), 2 (Agent environment), 3 (Azure environment), 4 (Edge agent environment) or 5 (Local Kubernetes Environment)',
                }),
              ContainerEngine: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "Container engine used by the environment(endpoint). Value must be one of: 'docker' or 'podman'",
                }),
              URL: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'URL or IP address of a Docker host (example: docker.mydomain.tld:2375). Defaults to local if not specified (Linux: /var/run/docker.sock, Windows: //./pipe/docker_engine). Cannot be empty if EndpointCreationType is set to 4 (Edge agent environment)',
                }),
              PublicURL: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'URL or IP address where exposed containers will be reachable. Defaults to URL if not specified (example: docker.mydomain.tld:2375)',
                }),
              GroupID: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Environment(Endpoint) group identifier. If not specified will default to 1 (unassigned).',
                }),
              TLS: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Require TLS to connect against this environment(endpoint). Must be true if EndpointCreationType is set to 2 (Agent environment)',
                }),
              TLSSkipVerify: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Skip server verification when using TLS. Must be true if EndpointCreationType is set to 2 (Agent environment)',
                }),
              TLSSkipClientVerify: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Skip client verification when using TLS. Must be true if EndpointCreationType is set to 2 (Agent environment)',
                }),
              TLSCACertFile: z
                .file()
                .exactOptional()
                .openapi({
                  type: 'string',
                  format: 'binary',
                  description: 'TLS CA certificate file',
                }),
              TLSCertFile: z
                .file()
                .exactOptional()
                .openapi({
                  type: 'string',
                  format: 'binary',
                  description: 'TLS client certificate file',
                }),
              TLSKeyFile: z
                .file()
                .exactOptional()
                .openapi({ type: 'string', format: 'binary', description: 'TLS client key file' }),
              AzureApplicationID: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Azure application ID. Required if environment(endpoint) type is set to 3',
                }),
              AzureTenantID: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Azure tenant ID. Required if environment(endpoint) type is set to 3',
                }),
              AzureAuthenticationKey: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Azure authentication key. Required if environment(endpoint) type is set to 3',
                }),
              TagIds: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'JSON-parsable array of tag identifiers to which this environment(endpoint) is associated',
                }),
              EdgeCheckinInterval: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({ description: 'The check in interval for edge agent (in seconds)' }),
              EdgeTunnelServerAddress: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'URL or IP address that will be used to establish a reverse tunnel',
                }),
              Gpus: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'List of GPUs - json stringified array of {name, value} structs',
                }),
            })
            .openapi({ required: ['Name', 'EndpointCreationType'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: PortainerEndpointSchema } },
    },
    400: { description: 'Invalid request' },
    409: { description: 'Name is not unique' },
    500: { description: 'Server error' },
  },
  security: [{ ApiKeyAuth: [] }, { jwt: [] }],
})

export const deleteEndpointsRoute = createRoute({
  method: 'delete',
  path: '/endpoints',
  tags: ['endpoints'],
  summary: 'Remove multiple environments',
  description:
    'Deprecated: use the `POST` endpoint instead.\nRemove multiple environments and optionally clean-up associated resources.\n**Access policy**: Administrator only.',
  operationId: 'EndpointDeleteBatchDeprecated',
  request: { body: EndpointsEndpointDeleteBatchPayloadRequestBody },
  responses: {
    204: { description: 'Environment(s) successfully deleted.' },
    207: {
      description:
        'Partial success. Some environments were deleted successfully, while others failed.',
      content: {
        'application/json': { schema: EndpointsEndpointDeleteBatchPartialResponseSchema },
      },
    },
    400: {
      description:
        'Invalid request payload, such as missing required fields or fields not meeting validation criteria.',
    },
    403: { description: 'Unauthorized access or operation not allowed.' },
    500: {
      description: 'Server error occurred while attempting to delete the specified environments.',
    },
  },
  deprecated: true,
  security: [{ ApiKeyAuth: [], jwt: [] }],
})

