export const getKubernetesConfigRoute = createRoute({
  method: 'get',
  path: '/kubernetes/config',
  tags: ['kubernetes'],
  summary: 'Generate a kubeconfig file',
  description:
    'Generate a kubeconfig file that allows a client to communicate with the Kubernetes API server\n**Access policy**: Authenticated user.',
  operationId: 'GetKubernetesConfig',
  request: {
    query: z.object({
      ids: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(
            z.preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            ),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'will include only these environments(endpoints)',
            in: 'query',
            name: 'ids',
            style: 'form',
            explode: false,
            schema: { type: 'array', items: { type: 'integer' } },
            required: false,
          },
        }),
      excludeIds: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(
            z.preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            ),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'will exclude these environments(endpoints)',
            in: 'query',
            name: 'excludeIds',
            style: 'form',
            explode: false,
            schema: { type: 'array', items: { type: 'integer' } },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: {
        'application/json': { schema: z.any() },
        ' application/yaml': { schema: z.any() },
      },
    },
    400: {
      description:
        'Invalid request payload, such as missing required fields or fields not meeting validation criteria.',
    },
    401: {
      description:
        'Unauthorized access - the user is not authenticated or does not have the necessary permissions. Ensure that you have provided a valid API key or JWT token, and that you have the required permissions.',
    },
    403: {
      description:
        'Permission denied - the user is authenticated but does not have the necessary permissions to access the requested resource or perform the specified operation. Check your user roles and permissions.',
    },
    404: { description: 'Unable to find an environment with the specified identifier.' },
    500: { description: 'Server error occurred while attempting to generate the kubeconfig file.' },
  },
  security: [{ ApiKeyAuth: [], jwt: [] }],
})

